-- =====================================================================================
-- Approval Rate Copilot | Lakeflow pipeline, Spark Declarative Pipelines: bronze, reference and silver
-- Generated by tools/build_databricks.py from the SQL bodies in /sql. Do not edit by hand.
-- Data: 100% synthetic. Fictional orchestrator, acquirers (A, B, C), issuers and merchants.
-- =====================================================================================
-- Pipeline settings: default catalog `workspace`, default schema `approval_copilot`,
-- serverless, triggered mode. Source files land in /Volumes/workspace/approval_copilot/landing.
-- All local-time columns assume the session time zone is UTC (Databricks default).
-- The gold tables are built after the pipeline by the dbt project in dbt/ (a task of the job).

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH STREAMING TABLE bronze_orchestrator
COMMENT 'Raw payment intents from the orchestrator, as received.'
AS
-- Raw orchestrator files as received (all columns kept as strings), plus lineage columns.
SELECT
  *,
  _metadata.file_name AS _source_file,
  current_timestamp() AS _ingested_at
FROM STREAM read_files('/Volumes/workspace/approval_copilot/landing/raw/orchestrator/', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH STREAMING TABLE bronze_acquirer_a
COMMENT 'Raw authorization responses from Acquirer A (ISO-8601 UTC, decimal amounts).'
AS
-- Raw acquirer_a files as received (all columns kept as strings), plus lineage columns.
SELECT
  *,
  _metadata.file_name AS _source_file,
  current_timestamp() AS _ingested_at
FROM STREAM read_files('/Volumes/workspace/approval_copilot/landing/raw/acquirer_a/', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH STREAMING TABLE bronze_acquirer_b
COMMENT 'Raw authorization responses from Acquirer B (local time + offset, minor units, R-codes).'
AS
-- Raw acquirer_b files as received (all columns kept as strings), plus lineage columns.
SELECT
  *,
  _metadata.file_name AS _source_file,
  current_timestamp() AS _ingested_at
FROM STREAM read_files('/Volumes/workspace/approval_copilot/landing/raw/acquirer_b/', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH STREAMING TABLE bronze_acquirer_c
COMMENT 'Raw authorization responses from Acquirer C (epoch millis, comma decimals, Portuguese labels).'
AS
-- Raw acquirer_c files as received (all columns kept as strings), plus lineage columns.
SELECT
  *,
  _metadata.file_name AS _source_file,
  current_timestamp() AS _ingested_at
FROM STREAM read_files('/Volumes/workspace/approval_copilot/landing/raw/acquirer_c/', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_merchants
COMMENT 'Merchant reference data (fictional). Grain: one row per merchant.'
AS
SELECT
  merchant_id,
  country,
  segment,
  mcc,
  CAST(avg_ticket_usd AS DOUBLE) AS avg_ticket_usd,
  CAST(concat(replace(onboarded_utc, ' ', 'T'), ':00Z') AS TIMESTAMP) AS onboarded_ts_utc
FROM read_files('/Volumes/workspace/approval_copilot/landing/reference/merchants.csv', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_issuers
COMMENT 'Card issuer reference data (fictional issuers). Grain: one row per issuer.'
AS
SELECT
  issuer_id,
  issuer_country,
  CAST(market_share AS DOUBLE) AS market_share,
  issuer_type
FROM read_files('/Volumes/workspace/approval_copilot/landing/reference/issuers.csv', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_acquirers
COMMENT 'Acquirers and their fees in basis points (synthetic). Grain: one row per acquirer.'
AS
SELECT
  acquirer_id,
  acquirer_name,
  countries,
  CAST(fee_bps AS INT) AS fee_bps,
  raw_format
FROM read_files('/Volumes/workspace/approval_copilot/landing/reference/acquirers.csv', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_routing_rules
COMMENT 'Versioned routing rules: traffic share per acquirer. Grain: one row per routing version × validity period × country × card type × acquirer.'
AS
SELECT
  routing_version,
  CAST(concat(replace(valid_from_utc, ' ', 'T'), 'Z') AS TIMESTAMP) AS valid_from_utc,
  CAST(concat(replace(valid_to_utc, ' ', 'T'), 'Z') AS TIMESTAMP) AS valid_to_utc,
  country,
  card_type,
  scope,
  acquirer_id,
  CAST(traffic_share AS DOUBLE) AS traffic_share
FROM read_files('/Volumes/workspace/approval_copilot/landing/reference/routing_rules.csv', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_decline_code_map
COMMENT 'Versioned map from raw acquirer status/code to canonical status, decline type and retryability. Grain: one row per mapping version × source system × raw status × raw code.'
AS
-- Versioned normalization map: (source system, raw status, raw code) -> canonical status.
-- 18 raw statuses across 4 source systems collapse into 8 canonical statuses.
SELECT
  mapping_version,
  CAST(concat(replace(valid_from_utc, ' ', 'T'), 'Z') AS TIMESTAMP) AS valid_from_utc,
  CAST(concat(replace(valid_to_utc, ' ', 'T'), 'Z') AS TIMESTAMP) AS valid_to_utc,
  source_system,
  raw_status,
  coalesce(raw_code, '') AS raw_code,
  nullif(iso_code, '') AS iso_code,
  reason,
  canonical_status,
  decline_type,
  CAST(retryable AS BOOLEAN) AS retryable
FROM read_files('/Volumes/workspace/approval_copilot/landing/reference/decline_code_map.csv', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_change_log
COMMENT 'Production changes: releases, routing, risk and mapping updates. Grain: one row per production change.'
AS
SELECT
  change_id,
  CAST(concat(replace(changed_at_utc, ' ', 'T'), 'Z') AS TIMESTAMP) AS changed_at_utc,
  change_type,
  scope,
  description,
  owner_team
FROM read_files('/Volumes/workspace/approval_copilot/landing/reference/change_log.csv', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_fx_rates
COMMENT 'Fixed synthetic FX rates to USD. Grain: one row per currency.'
AS
SELECT
  currency,
  CAST(usd_rate AS DOUBLE) AS usd_rate
FROM read_files('/Volumes/workspace/approval_copilot/landing/reference/fx_rates.csv', format => 'csv', header => true, inferColumnTypes => false);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ref_country_tz
COMMENT 'Country time zones and currencies. Grain: one row per country.'
AS
-- None of the three countries observes daylight saving time in 2026.
SELECT * FROM VALUES
  ('MX', 'America/Mexico_City', 'MXN'),
  ('CO', 'America/Bogota', 'COP'),
  ('BR', 'America/Sao_Paulo', 'BRL')
  AS t(country, time_zone, currency);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW silver_payment_intents
(
  payment_id STRING,
  merchant_id STRING,
  created_ts_utc TIMESTAMP,
  country STRING,
  currency STRING,
  amount DECIMAL(18,2),
  card_brand STRING,
  card_type STRING,
  issuer_id STRING,
  is_cross_border BOOLEAN,
  installments INT,
  three_ds_requested BOOLEAN,
  three_ds_flow STRING,
  orchestrator_status STRING,
  routing_rule_version STRING,
  first_acquirer_id STRING,
  channel STRING,
  card_bin STRING,
  card_last4 STRING MASK workspace.approval_copilot.mask_card_last4,
  CONSTRAINT has_merchant EXPECT (merchant_id IS NOT NULL)
)
COMMENT 'Payment intents from the orchestrator, typed and cleaned. Grain: one row per payment intent.'
AS
-- One row per payment intent logged by the orchestrator, typed and cleaned.
-- Timestamps arrive as UTC strings without an offset; we make the offset explicit
-- so the result does not depend on the session time zone.
SELECT
  payment_id,
  nullif(merchant_id, '') AS merchant_id,
  CAST(concat(replace(created_at_utc, ' ', 'T'), 'Z') AS TIMESTAMP) AS created_ts_utc,
  country,
  currency,
  CAST(amount AS DECIMAL(18, 2)) AS amount,
  lower(card_brand) AS card_brand,
  card_type,
  issuer_id,
  CAST(is_cross_border AS BOOLEAN) AS is_cross_border,
  CAST(installments AS INT) AS installments,
  CAST(three_ds_requested AS BOOLEAN) AS three_ds_requested,
  nullif(three_ds_flow, '') AS three_ds_flow,
  orchestrator_status,
  nullif(routing_rule_version, '') AS routing_rule_version,
  nullif(first_acquirer, '') AS first_acquirer_id,
  channel,
  -- Truncated card number only (BIN and last four), never the full number. On Databricks the last
  -- four digits carry a column mask (see the pipeline definition and notebook 00).
  card_bin,
  card_last4
FROM bronze_orchestrator;

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW silver_auth_attempts_staged
COMMENT 'All authorization attempts harmonized across acquirers, deduplicated and mapped (before quality rules).'
AS
-- Harmonizes three acquirer formats into one schema, removes webhook re-deliveries,
-- and maps each raw (status, code) pair to a canonical status using the mapping
-- version that was active when the attempt happened.
WITH a AS (
  SELECT
    'A' AS acquirer_id,
    event_id AS source_event_id,
    payment_ref AS payment_id,
    merchant_ref AS merchant_id,
    CAST(created_at_utc AS TIMESTAMP) AS attempt_ts_utc,            -- ISO-8601 with Z
    CAST(received_at_utc AS TIMESTAMP) AS received_ts_utc,
    CAST(amount AS DECIMAL(18, 2)) AS amount,
    currency,
    country,
    lower(card_brand) AS card_brand,
    lower(card_type) AS card_type,
    issuer_ref AS issuer_id,
    CAST(is_3ds AS BOOLEAN) AS is_3ds_authenticated,
    CAST(installments AS INT) AS installments,
    status AS raw_status,
    coalesce(response_code, '') AS raw_code,
    CAST(latency_ms AS INT) AS latency_ms,
    CAST(attempt_seq AS INT) AS attempt_seq
  FROM bronze_acquirer_a
),
b AS (
  SELECT
    'B' AS acquirer_id,
    id AS source_event_id,
    order_id AS payment_id,
    merchant AS merchant_id,
    -- local "dd/MM/yyyy HH:mm:ss" + offset "-05:00" -> ISO-8601 with offset -> UTC instant
    CAST(concat(substr(local_datetime, 7, 4), '-', substr(local_datetime, 4, 2), '-', substr(local_datetime, 1, 2),
                'T', substr(local_datetime, 12, 8), tz_offset) AS TIMESTAMP) AS attempt_ts_utc,
    CAST(NULL AS TIMESTAMP) AS received_ts_utc,
    CAST(CAST(amount_minor AS DECIMAL(20, 0)) / 100 AS DECIMAL(18, 2)) AS amount,  -- minor units
    ccy AS currency,
    ctry AS country,
    CASE upper(brand) WHEN 'MC' THEN 'mastercard' ELSE lower(brand) END AS card_brand,
    lower(funding) AS card_type,
    issuer AS issuer_id,
    auth_3ds = 'Y' AS is_3ds_authenticated,
    CAST(cuotas AS INT) AS installments,
    result AS raw_status,
    coalesce(reason_code, '') AS raw_code,
    CAST(resp_time_ms AS INT) AS latency_ms,
    CAST(try_no AS INT) AS attempt_seq
  FROM bronze_acquirer_b
),
c AS (
  SELECT
    'C' AS acquirer_id,
    transacao_id AS source_event_id,
    pedido_id AS payment_id,
    loja_id AS merchant_id,
    timestamp_millis(CAST(timestamp_ms AS BIGINT)) AS attempt_ts_utc,  -- epoch millis
    CAST(NULL AS TIMESTAMP) AS received_ts_utc,
    CAST(replace(valor, ',', '.') AS DECIMAL(18, 2)) AS amount,          -- comma decimals
    coalesce(nullif(moeda, ''),
             CASE pais WHEN 'BR' THEN 'BRL' WHEN 'MX' THEN 'MXN' WHEN 'CO' THEN 'COP' END) AS currency,
    pais AS country,
    lower(bandeira) AS card_brand,
    CASE tipo_cartao WHEN 'CREDITO' THEN 'credit' WHEN 'DEBITO' THEN 'debit' END AS card_type,
    emissor AS issuer_id,
    autenticado_3ds = '1' AS is_3ds_authenticated,
    CAST(parcelas AS INT) AS installments,
    situacao AS raw_status,
    coalesce(codigo_retorno, '') AS raw_code,
    CAST(tempo_resposta_ms AS INT) AS latency_ms,
    CAST(tentativa AS INT) AS attempt_seq
  FROM bronze_acquirer_c
),
unioned AS (
  SELECT * FROM a
  UNION ALL SELECT * FROM b
  UNION ALL SELECT * FROM c
),
ranked AS (
  -- Acquirer A re-delivers some webhooks: keep the first copy of each event
  SELECT
    u.*,
    row_number() OVER (PARTITION BY acquirer_id, source_event_id
                       ORDER BY received_ts_utc NULLS LAST) AS delivery_rank
  FROM unioned u
),
deduplicated AS (
  SELECT
    acquirer_id, source_event_id, payment_id, merchant_id, attempt_ts_utc, received_ts_utc,
    amount, currency, country, card_brand, card_type, issuer_id, is_3ds_authenticated,
    installments, raw_status, raw_code, latency_ms, attempt_seq
  FROM ranked
  WHERE delivery_rank = 1
)
SELECT
  d.*,
  m.mapping_version,
  m.canonical_status,
  m.iso_code,
  m.reason,
  m.decline_type,
  m.retryable,
  m.canonical_status IN ('APPROVED', 'REVERSED') AS is_authorized
FROM deduplicated d
LEFT JOIN ref_decline_code_map m
  ON m.source_system = d.acquirer_id
 AND m.raw_status = d.raw_status
 AND m.raw_code = d.raw_code
 AND d.attempt_ts_utc >= m.valid_from_utc
 AND d.attempt_ts_utc < m.valid_to_utc;

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW silver_auth_attempts
(
  CONSTRAINT has_payment_id EXPECT (payment_id IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT valid_timestamp EXPECT (attempt_ts_utc IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT valid_amount EXPECT (coalesce(amount > 0, false)) ON VIOLATION DROP ROW,
  CONSTRAINT mapped_code EXPECT (canonical_status IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Authorization attempts that pass the data-quality rules. Grain: one row per authorization attempt (after de-duplication and quality rules).'
AS
-- Attempts that pass the data-quality expectations defined for this table
-- (see the pipeline definition). Failing rows go to silver_dq_quarantine.
SELECT * FROM silver_auth_attempts_staged;

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW silver_dq_quarantine
COMMENT 'Attempts rejected by the data-quality rules, with the rule they failed. Grain: one row per rejected authorization attempt.'
AS
-- Rows rejected by the data-quality rules, with the first rule they failed.
-- Kept for investigation instead of being silently dropped.
SELECT
  s.*,
  CASE
    WHEN s.payment_id IS NULL THEN 'has_payment_id'
    WHEN s.attempt_ts_utc IS NULL THEN 'valid_timestamp'
    WHEN NOT coalesce(s.amount > 0, false) THEN 'valid_amount'
    WHEN s.canonical_status IS NULL THEN 'mapped_code'
  END AS failed_rule
FROM silver_auth_attempts_staged s
WHERE NOT (
  s.payment_id IS NOT NULL
  AND s.attempt_ts_utc IS NOT NULL
  AND coalesce(s.amount > 0, false)
  AND s.canonical_status IS NOT NULL
);

-- ------------------------------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW silver_payments
COMMENT 'One row per payment with first attempt, cascade attempt and final outcome. Grain: one row per payment intent.'
AS
-- One row per payment: the intent, its first authorization attempt, the cascade
-- attempt on a second acquirer (if any) and the final outcome.
WITH first_att AS (
  SELECT * FROM silver_auth_attempts WHERE attempt_seq = 1
),
cascade_att AS (
  SELECT * FROM silver_auth_attempts WHERE attempt_seq = 2
),
orchestrator_map AS (
  SELECT DISTINCT raw_status, canonical_status
  FROM ref_decline_code_map
  WHERE source_system = 'ORCHESTRATOR'
),
joined AS (
  SELECT
    i.payment_id,
    coalesce(i.merchant_id, 'UNKNOWN') AS merchant_id,
    coalesce(m.segment, 'unknown') AS merchant_segment,
    m.mcc,
    i.country,
    i.currency,
    i.amount,
    round(i.amount / fx.usd_rate, 2) AS amount_usd,
    i.card_brand,
    i.card_type,
    i.issuer_id,
    i.is_cross_border,
    i.installments,
    i.three_ds_requested,
    i.three_ds_flow,
    i.channel,
    i.created_ts_utc,
    from_utc_timestamp(i.created_ts_utc, tz.time_zone) AS created_ts_local,
    i.orchestrator_status,
    i.routing_rule_version,
    f.payment_id IS NOT NULL AS sent_to_acquirer,
    i.orchestrator_status = 'ROUTED' AND f.payment_id IS NULL AS missing_attempt_data,
    f.acquirer_id AS first_acquirer_id,
    f.canonical_status AS first_status,
    f.iso_code AS first_iso_code,
    f.reason AS first_reason,
    f.decline_type AS first_decline_type,
    f.retryable AS first_retryable,
    f.mapping_version AS first_mapping_version,
    f.latency_ms AS first_latency_ms,
    f.is_3ds_authenticated,
    s.payment_id IS NOT NULL AS is_cascaded,
    s.acquirer_id AS cascade_acquirer_id,
    s.canonical_status AS cascade_status,
    s.iso_code AS cascade_iso_code,
    coalesce(f.is_authorized, false) AS first_attempt_approved,
    coalesce(s.is_authorized, false) AS cascade_approved,
    CASE
      WHEN i.orchestrator_status <> 'ROUTED' THEN om.canonical_status
      ELSE coalesce(s.canonical_status, f.canonical_status)
    END AS final_status
  FROM silver_payment_intents i
  JOIN ref_country_tz tz ON tz.country = i.country
  LEFT JOIN first_att f ON f.payment_id = i.payment_id
  LEFT JOIN cascade_att s ON s.payment_id = i.payment_id
  LEFT JOIN ref_merchants m ON m.merchant_id = i.merchant_id
  LEFT JOIN ref_fx_rates fx ON fx.currency = i.currency
  LEFT JOIN orchestrator_map om ON om.raw_status = i.orchestrator_status
),
outcomes AS (
  SELECT
    j.*,
    to_date(j.created_ts_local) AS business_date,
    hour(j.created_ts_local) AS hour_local,
    j.first_attempt_approved OR j.cascade_approved AS final_approved,
    NOT j.first_attempt_approved AND j.cascade_approved AS recovered_by_cascade,
    CASE
      WHEN j.first_attempt_approved THEN j.first_acquirer_id
      WHEN j.cascade_approved THEN j.cascade_acquirer_id
    END AS approving_acquirer_id
  FROM joined j
)
SELECT
  o.*,
  CASE WHEN o.final_approved THEN o.amount_usd ELSE 0 END AS approved_usd,
  round(CASE WHEN o.final_approved THEN o.amount_usd * a.fee_bps / 10000 ELSE 0 END, 4) AS fee_usd
FROM outcomes o
LEFT JOIN ref_acquirers a ON a.acquirer_id = o.approving_acquirer_id;
